import 'dart:convert';
import 'dart:typed_data';

/// A bundled Turkish qualified-electronic-signature CA certificate used as a
/// trust anchor. Chains that terminate at one of these (verified
/// cryptographically) are reported as trusted.
class TrustAnchor {
  const TrustAnchor({
    required this.name,
    required this.sha256Fingerprint,
    required this.derBase64,
  });

  final String name;

  /// Uppercase hex SHA-256 of the DER certificate, no separators.
  final String sha256Fingerprint;

  final String derBase64;

  Uint8List get der => base64Decode(derBase64);
}

/// Bundled root/CA certificates for the major Turkish qualified ESHS
/// providers (Kamu SM / TÜBİTAK BİLGEM, EBG / E-Tuğra). Fetched from the
/// providers' public repositories; fingerprints double-checked with openssl.
///
/// To trust an additional CA, add its DER (base64) and SHA-256 fingerprint
/// here — no other code change is needed. Root expiry is intentionally not
/// enforced: a root is a pinned identity, and documents signed while it was
/// valid must still verify.
